var xhr = new XMLHttpRequest();
xhr.open('GET', '/api/marks.json', true);
xhr.onreadystatechange = function () {
  if (xhr.readyState !== 4) return;
  if (xhr.status !== 200) {
    document.getElementById('out').textContent = 'Error ' + xhr.status;
    return;
  }
  var data = JSON.parse(xhr.responseText);
  document.getElementById('out').textContent = data[0].name + ': ' + data[0].marks;
};
xhr.onerror = function () {
  document.getElementById('out').textContent = 'Network error';
};
xhr.send(null);
